<?php
namespace App\Services; use App\Repositories\UserRepository;
final class AuthService {
    public function __construct(private ?UserRepository $users=null){$this->users??=new UserRepository();}
    public function validateRegistration(array $d):array{$e=[]; foreach(['first_name','last_name','second_last_name','username','email','password','password_confirm'] as $f) if(trim((string)($d[$f]??''))==='')$e[$f]='Campo obligatorio.'; if(!filter_var($d['email']??'',FILTER_VALIDATE_EMAIL))$e['email']='Correo no válido.'; $p=$d['password']??''; if(strlen($p)<8||!preg_match('/[A-Z]/',$p)||!preg_match('/[a-z]/',$p)||!preg_match('/\d/',$p)||!preg_match('/[^A-Za-z0-9]/',$p))$e['password']='Usa 8+ caracteres, mayúscula, minúscula, número y símbolo.'; if(($d['password']??'')!==($d['password_confirm']??''))$e['password_confirm']='Las contraseñas no coinciden.'; if(!$e && $this->users->existsUsernameOrEmail($d['username'],$d['email']))$e['username']='El usuario o correo ya está registrado.'; return $e;}
    public function authenticate(string $u,string $p):?array{$user=$this->users->findByUsername($u); if(!$user||$user['status']!=='ACTIVE'||!password_verify($p,$user['password_hash']))return null; return $user;}
    public function validateBuyerRegistration(array $d):array{$e=[];foreach(['first_name','last_name','username','password','password_confirm'] as $f)if(trim((string)($d[$f]??''))==='')$e[$f]='Campo obligatorio.';$p=$d['password']??'';if(strlen($p)<8||!preg_match('/[A-Z]/',$p)||!preg_match('/[a-z]/',$p)||!preg_match('/\d/',$p)||!preg_match('/[^A-Za-z0-9]/',$p))$e['password']='Usa 8+ caracteres, mayúscula, minúscula, número y símbolo.';if(($d['password']??'')!==($d['password_confirm']??''))$e['password_confirm']='Las contraseñas no coinciden.';if(!$e&&$this->users->existsUsernameOrEmail($d['username'],$d['email']))$e['username']='El nombre de usuario ya está registrado.';return $e;}
}
